# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">XI-XIII. YÜZYILLARDA TÜRK-İSLAM MEDENİYETİ İLE BATI MEDENİYETİ KARŞILAŞTIRMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">TÜRK-İSLAM MEDENİYETİ (ALTIN ÇAĞ)</text>\n  <text x="34" y="88" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Bilim Anlayışı:</tspan> Deney, gözlem ve akla dayalı özgür</text>\n  <text x="44" y="104" font-size="10.3" fill="#14532d">araştırma; İsfahan ve Cacabey rasathaneleri.</text>\n  <text x="34" y="126" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Eğitim (Medrese):</tspan> Vakıf destekli parasız-burslu</text>\n  <text x="44" y="142" font-size="10.3" fill="#14532d">eğitim; aklî ve naklî ilimlerin birlikte okutulması.</text>\n  <text x="34" y="164" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Sağlık (Darüşşifa):</tspan> Gevher Nesibe ve Divriği</text>\n  <text x="44" y="180" font-size="10.3" fill="#14532d">darüşşifalarında ücretsiz tıp, su sesi ve müzikle tedavi.</text>\n  <text x="34" y="202" font-size="10.6" font-weight="bold" fill="#15803d">• Farklı inanç ve kültürlere hoşgörü (İstimanet).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#991b1b">ORTA ÇAĞ BATI (AVRUPA) MEDENİYETİ</text>\n  <text x="370" y="88" font-size="10.6" fill="#7f1d1d">• <tspan font-weight="bold">Bilim Anlayışı:</tspan> Skolastik düşünce; deney ve</text>\n  <text x="380" y="104" font-size="10.3" fill="#7f1d1d">eleştirinin yasaklanması, engizisyon baskısı.</text>\n  <text x="370" y="126" font-size="10.6" fill="#7f1d1d">• <tspan font-weight="bold">Eğitim:</tspan> Kilise ve manastır tekelinde sınırlı</text>\n  <text x="380" y="142" font-size="10.3" fill="#7f1d1d">eğitim; halkın büyük çoğunluğunda okuryazarlık yokluğu.</text>\n  <text x="370" y="164" font-size="10.6" fill="#7f1d1d">• <tspan font-weight="bold">Sağlık:</tspan> Salgın hastalıkların ve akıl hastalıklarının</text>\n  <text x="380" y="180" font-size="10.3" fill="#7f1d1d">büyü/cadılık sayılması; bilimsel tıbbın gerilemesi.</text>\n  <text x="370" y="202" font-size="10.6" font-weight="bold" fill="#991b1b">• İslam eserlerinin tercümesiyle uyanışa geçiş.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Türk-İslam medeniyeti, bilim ve insan onuruna verdiği değerle insanlığın ortak mirasına öncülük etmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRKİSTAN\'DAN TÜRKİYE\'YE ORTAK MİRASA KATKI SUNAN ŞAHSİYETLER VE ESERLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">BİLİM, DİL VE TARİH ÖNCÜLERİ</text>\n  <text x="34" y="88" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kaşgarlı Mahmud:</tspan> Dîvânu Lugâti\'t-Türk (İlk Türkçe</text>\n  <text x="44" y="103" font-size="10.2" fill="#1e3a8a">ansiklopedik sözlük, dil bilimi ve Türk dünyası haritası).</text>\n  <text x="34" y="124" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Ömer Hayyam:</tspan> İsfahan Rasathanesi, Celâlî Takvimi</text>\n  <text x="44" y="139" font-size="10.2" fill="#1e3a8a">ve üçüncü dereceden cebirsel denklemlerin çözümü.</text>\n  <text x="34" y="160" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">el-Cezerî (Artuklu):</tspan> Kitâbü\'l-Hiyel; sibernetik,</text>\n  <text x="44" y="175" font-size="10.2" fill="#1e3a8a">otomasyon, krank mili, su saatleri ve robotik öncüsü.</text>\n  <text x="34" y="198" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">İbn Bîbî:</tspan> el-Evâmirü\'l-Alâiyye (Türkiye Selçuklu tarihi).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">MANEVİ MİMARLAR VE GÖNÜL ERENLERİ</text>\n  <text x="370" y="88" font-size="10.5" fill="#713f12">• <tspan font-weight="bold">Hoca Ahmed Yesevî:</tspan> Dîvân-ı Hikmet; Türk tasavvuf</text>\n  <text x="380" y="103" font-size="10.2" fill="#713f12">geleneğinin kurucusu ve Horasan erenlerinin pîri.</text>\n  <text x="370" y="124" font-size="10.5" fill="#713f12">• <tspan font-weight="bold">İbnü\'l-Arabî &amp; Sadreddin Konevî:</tspan> Tasavvuf felsefesi.</text>\n  <text x="370" y="145" font-size="10.5" fill="#713f12">• <tspan font-weight="bold">Mevlânâ Celâleddin-i Rûmî:</tspan> Mesnevî, Dîvân-ı Kebîr.</text>\n  <text x="370" y="166" font-size="10.5" fill="#713f12">• <tspan font-weight="bold">Hacı Bektaş Velî:</tspan> Makâlât; dört kapı kırk makam.</text>\n  <text x="370" y="187" font-size="10.5" fill="#713f12">• <tspan font-weight="bold">Yunus Emre:</tspan> Risâletü\'n-Nushiyye ve Dîvân; Anadolu\'da</text>\n  <text x="380" y="202" font-size="10.2" fill="#713f12">Türkçenin edebiyat ve irfan dili olmasının öncüsü.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Mimari eserler Anadolu\'nun maddi tapu senedi, erenlerin ve âlimlerin eserleri ise manevi tapu senedidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1. ÜNİTE BÜTÜNCÜL ÖZETİ: TÜRKİSTAN\'DAN TÜRKİYE\'YE (1040 - 1299)</text>\n  <rect x="18" y="42" width="158" height="172" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#1e40af">1. ASKERÎ KRONOLOJİ</text>\n  <text x="28" y="84" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">1040 Dandanakan:</tspan> Büyük</text>\n  <text x="34" y="98" font-size="10" fill="#1e3a8a">Selçuklu\'nun kuruluşu.</text>\n  <text x="28" y="118" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">1048 Pasinler:</tspan> İlk keşif.</text>\n  <text x="28" y="138" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">1071 Malazgirt:</tspan> Yurt açan</text>\n  <text x="34" y="152" font-size="10" fill="#1e3a8a">zafer ve İlk Beylikler.</text>\n  <text x="28" y="172" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">1176 Miryokefalon:</tspan> Yurt</text>\n  <text x="34" y="186" font-size="10" fill="#1e3a8a">tutan zafer (II. Kılıç Arslan).</text>\n  <text x="28" y="204" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">1243 Kösedağ:</tspan> Moğol istilası.</text>\n  <rect x="186" y="42" width="158" height="172" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="265" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#166534">2. DEVLET VE ORDU</text>\n  <text x="196" y="84" font-size="10" fill="#14532d">• Kut ve cihan hâkimiyeti</text>\n  <text x="202" y="98" font-size="10" fill="#14532d">+ Cihat ve gaza anlayışı.</text>\n  <text x="196" y="118" font-size="10" fill="#14532d">• <tspan font-weight="bold">Dîvân-ı Saltanat:</tspan> Merkezî</text>\n  <text x="202" y="132" font-size="10" fill="#14532d">hükûmet; Melik ve Atabey.</text>\n  <text x="196" y="152" font-size="10" fill="#14532d">• <tspan font-weight="bold">İkta Sistemi:</tspan> Toprak</text>\n  <text x="202" y="166" font-size="10" fill="#14532d">geliriyle beslenen sipahi</text>\n  <text x="202" y="180" font-size="10" fill="#14532d">ordusu ve üretim sürekliliği.</text>\n  <text x="196" y="200" font-size="10" fill="#14532d">• <tspan font-weight="bold">Gulâmân-ı Saray</tspan> ordusu.</text>\n  <rect x="354" y="42" width="158" height="172" rx="8" fill="#ffedd5" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="433" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#9a3412">3. TOPLUM VE EKONOMİ</text>\n  <text x="364" y="84" font-size="10" fill="#7c2d12">• Konargöçer Oğuzların</text>\n  <text x="370" y="98" font-size="10" fill="#7c2d12">iskânı ve şehirleşme.</text>\n  <text x="364" y="118" font-size="10" fill="#7c2d12">• <tspan font-weight="bold">Ahilik Teşkilatı:</tspan> Ahi Evran,</text>\n  <text x="370" y="132" font-size="10" fill="#7c2d12">Bacıyan-ı Rum, meslek etiği</text>\n  <text x="370" y="146" font-size="10" fill="#7c2d12">ve kalite denetimi.</text>\n  <text x="364" y="166" font-size="10" fill="#7c2d12">• <tspan font-weight="bold">Ticaret Ağı:</tspan> Kervansaraylar</text>\n  <text x="370" y="180" font-size="10" fill="#7c2d12">(ribat), liman fetihleri ve</text>\n  <text x="370" y="194" font-size="10" fill="#7c2d12">devlet ticaret sigortası.</text>\n  <rect x="522" y="42" width="160" height="172" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="602" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#6b21a8">4. BİLİM VE KÜLTÜR</text>\n  <text x="532" y="84" font-size="10" fill="#581c87">• Nizâmiye ve Anadolu</text>\n  <text x="538" y="98" font-size="10" fill="#581c87">medreseleri (parasız eğitim).</text>\n  <text x="532" y="118" font-size="10" fill="#581c87">• Darüşşifalar ve rasathaneler.</text>\n  <text x="532" y="138" font-size="10" fill="#581c87">• Kaşgarlı Mahmud, Hayyam,</text>\n  <text x="538" y="152" font-size="10" fill="#581c87">Cezerî, İbn Bîbî.</text>\n  <text x="532" y="172" font-size="10" fill="#581c87">• Yesevî, Mevlânâ, Hacı</text>\n  <text x="538" y="186" font-size="10" fill="#581c87">Bektaş Velî, Yunus Emre.</text>\n  <text x="532" y="202" font-size="10" fill="#581c87">• Camiler, kümbetler, çini.</text>\n  <rect x="18" y="222" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="239" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">1071 Malazgirt yurt açan, 1176 Miryokefalon yurt tutan zaferdir; bilim, vakıf ve irfan ise Anadolu\'yu vatanlaştırmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
